-- Seed registro chiamate generato dall'ultimo backup Google Drive
-- (calls-20260616225833.xml, 2118 chiamate).
-- Esegui questo file nello SQL Editor di Supabase: crea la tabella (se manca)
-- e inserisce tutte le chiamate. Re-eseguibile senza creare duplicati.

create extension if not exists pgcrypto;

create table if not exists public.calls (
  id uuid primary key default gen_random_uuid(),
  external_id text not null unique,
  number text,
  number_normalized text,
  contact_name text,
  duration int default 0,
  call_date timestamp with time zone not null,
  type int default 0,
  type_label text,
  client_id uuid references public.clients(id) on delete set null,
  created_at timestamp with time zone default now()
);

create index if not exists calls_call_date_idx on public.calls (call_date desc);
create index if not exists calls_number_normalized_idx on public.calls (number_normalized);
create index if not exists calls_client_id_idx on public.calls (client_id);

alter table public.calls enable row level security;
do $$
begin
  if not exists (select 1 from pg_policies where polname = 'open_access_calls') then
    create policy open_access_calls on public.calls for all using (true) with check (true);
  end if;
end $$;

on conflict (external_id) do nothing;

-- Collega le chiamate ai clienti confrontando le ultime 9 cifre del numero.
update public.calls c
set client_id = cl.id
from public.clients cl
where cl.phone is not null
  and right(regexp_replace(cl.phone, '[^0-9]', '', 'g'), 9) = right(c.number_normalized, 9)
  and length(c.number_normalized) >= 7;
